#!/usr/bin/env python3
"""Director-owned round9 ledger. Contributor records are preserved; no network."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def read(p):
 f=R/p
 return [json.loads(s) for s in f.read_text().splitlines() if s.strip()] if f.exists() else []
def write(p,rows):
 (R/p).write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
def upsert(p,rows):
 old={x['id']:x for x in read(p)}
 old.update({x['id']:x for x in rows});write(p,list(old.values()))
